struct Node {
    int key, val;
    Node *prev, *next;
    Node(int k = 0, int v = 0) : key(k), val(v), prev(nullptr), next(nullptr) {}
};

class LRUCache {
    int cap;
    unordered_map<int, Node*> cache;
    Node *head;  // 哨兵：head 后最新，tail 前最旧
    Node *tail;

    void remove(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    void addFront(Node* node) {
        node->prev = head;
        node->next = head->next;
        head->next->prev = node;
        head->next = node;
    }

public:
    LRUCache(int capacity) : cap(capacity) {
        head = new Node();
        tail = new Node();
        head->next = tail;
        tail->prev = head;
    }

    int get(int key) {
        unordered_map<int, Node*>::iterator it = cache.find(key);
        if (it == cache.end()) return -1;
        Node* node = it->second;
        remove(node);
        addFront(node);
        return node->val;
    }

    void put(int key, int value) {
        unordered_map<int, Node*>::iterator it = cache.find(key);
        if (it != cache.end()) {
            Node* node = it->second;
            node->val = value;
            remove(node);
            addFront(node);
            return;
        }
        if ((int)cache.size() == cap) {
            Node* last = tail->prev;
            remove(last);
            cache.erase(last->key);
        }
        Node* node = new Node(key, value);
        cache[key] = node;
        addFront(node);
    }
};

